describe('Search Functionality', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
    });

    it('should update search results as user types (happy path)', () => {
        cy.get('input[name="search"]').type('Cypress');
        cy.wait(300); // Wait for debounce time
        cy.get('.search-results').should('be.visible');
        cy.get('.search-results').children().should('have.length.greaterThan', 0);
        cy.get('.search-results').contains('Cypress');
    });

    it('should not update search results if input is cleared (edge case)', () => {
        cy.get('input[name="search"]').type('Cypress');
        cy.wait(300); // Wait for debounce time
        cy.get('input[name="search"]').clear();
        cy.wait(300); // Wait for debounce time
        cy.get('.search-results').should('not.exist');
    });
});
